const ORDER_IDEAS: Record<string, string[]> = {
  chinese: ["Noodles", "Vegetable dumplings", "Cucumber salad"],
  japanese: ["Ramen or udon", "Gyoza", "Edamame"],
  mexican: ["Tacos", "Chips and salsa", "Elote"],
